import unittest
from rosterkit.notices import absence_notice
from rosterkit.models import Mark, Student
from datetime import date

PUPIL = Student("7", "Rivera", "Ana", "A")
MIXED = (
    ("7", 9, "absent"),
    ("7", 4, "present"),
    ("7", 2, "absent")
)


def make_mark(ident, month, status):
    return Mark(ident, date(2026, 9, month), status)


def notice_for(*specs):
    marks = [make_mark(*item) for item in specs]
    return absence_notice(PUPIL, marks)


class NoticeTests(unittest.TestCase):
    def test_lists_dates_in_order(self):
        text = notice_for(*MIXED)
        want = "Ana Rivera missed 2 days: "
        want += "2026-09-02, 2026-09-09."
        self.assertEqual(text, want)

    def test_single_day(self):
        text = notice_for(("7", 3, "absent"))
        self.assertIn("missed 1 day:", text)

    def test_excused_not_counted(self):
        text = notice_for(
            ("7", 3, "excused"),
            ("7", 5, "absent")
        )
        self.assertIn("missed 1 day: 2026-09-05", text)

    def test_other_student(self):
        with self.assertRaises(ValueError):
            notice_for(
                ("7", 3, "absent"),
                ("8", 4, "absent")
            )

    def test_no_absences(self):
        with self.assertRaises(ValueError):
            notice_for(("7", 3, "late"))
        with self.assertRaises(ValueError):
            notice_for()
